(function(root){
root.createProfessionalWorkspace=function(ctx){
 let access=null,viewState=null;
 const esc=ctx.esc,$=s=>document.querySelector(s);
 const names={anesthesiste:'Anesthésiste',chirurgien:'Chirurgien',infirmier:'Infirmier',secretariat:'Secrétariat',pharmacien:'Pharmacien',dim:'DIM',facturation:'Facturation',administration:'Administration',unassigned:'Non attribué'};
 // Deux profils infirmiers : bloc (check-list HAS, ouverture des salles) et étage. Le métier reste « infirmier », le poste précise.
 // Pharmacie : pharmacien (titulaire, adjoint) ou préparateur en pharmacie (métier « pharmacien », poste « preparateur »).
 const metiers=Object.entries(names).flatMap(([id,l])=>id==='infirmier'?[['infirmier-bloc','Infirmier(ère) de bloc'],['infirmier-etage','Infirmier(ère) d’étage'],['infirmier-cadre','Cadre de bloc']]:id==='pharmacien'?[['pharmacien','Pharmacien'],['pharmacien-preparateur','Préparateur(trice) en pharmacie']]:[[id,l]]);
 const choix=(profession,poste)=>profession==='infirmier'?'infirmier-'+(['bloc','cadre'].includes(poste)?poste:'etage'):profession==='pharmacien'&&poste==='preparateur'?'pharmacien-preparateur':profession;
 const vers=v=>String(v||'').startsWith('infirmier-')?{profession:'infirmier',poste:v.slice(10)}:v==='pharmacien-preparateur'?{profession:'pharmacien',poste:'preparateur'}:v==='pharmacien'?{profession:'pharmacien',poste:'pharmacien'}:{profession:v,poste:''};
 const libelle=a=>a?.profession==='infirmier'?(a.poste==='cadre'?'Cadre de bloc':a.poste==='bloc'?'Infirmier(ère) de bloc':'Infirmier(ère) d’étage'):a?.profession==='pharmacien'&&a.poste==='preparateur'?'Préparateur(trice) en pharmacie':names[a?.profession]||a?.profession||'';
 async function api(path='',data){const r=await fetch('/api/workspace/access'+path,{credentials:'same-origin',cache:'no-store',...(data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{})});const result=await r.json();if(!r.ok)throw new Error(result.error||'Accès impossible');return result;}
 const option=(rows,value)=>rows.map(([id,label])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(label)}</option>`).join('');
 const select=(name,label,rows,value='')=>`<label>${label}<select name="${name}" aria-label="${label}">${option(rows,value)}</select></label>`;
 const field=(name,label,type='text',value='',required=true)=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} maxlength="500"></label>`;
 function form(id,title,body,button){return `<section class="panel"><div class="content"><h3>${title}</h3><form id="${id}"><div class="formgrid">${body}${field('reason','Motif de l’habilitation ou de sa modification')}</div><p role="alert" class="management-error"></p><button class="primary">${button}</button></form></div></section>`;}
 function canWrite(key){if(!access?.profile.active)return false;const job=access.profile.profession,[group,id,module]=key.split('/');if(group==='stay'&&module==='invitationContact')return ['anesthesiste','chirurgien','secretariat'].includes(job);if(group==='stay'&&module==='nursingRecord')return ['anesthesiste','chirurgien','infirmier'].includes(job);if(group==='stay'&&module==='checklistBloc'&&job==='infirmier'&&!['bloc','cadre'].includes(access.profile.poste))return false;if(group==='stay'&&['core','surgicalAnnouncement'].includes(module)&&job==='infirmier'&&access.profile.poste==='cadre')return true;if(group==='stay'&&module==='surgicalAnnouncement')return ['chirurgien','anesthesiste','secretariat'].includes(job);if(group==='stay'&&module==='medicationCircuit')return ['anesthesiste','chirurgien','pharmacien'].includes(job);if(group==='stay')return ({anesthesiste:['core','consult','perop','rx','notes','discharge','prepActions','postopVitals','scientificDecisions','questionnaire','events','aideCpa','prescriptionsPreop','vpa','checklistBloc','blocStatut','suiviAmbu','bionettoyage','envoisInterop','preadmission','periopPlus','peropRapide','soinsPlus','sortiePlus','codage','iaTrace','droitsRgpd'],chirurgien:['core','surgicalAnnouncement','cro','croDraft','prescriptionsPreop','rx','notes','discharge','prepActions','postopVitals','events','checklistBloc','blocStatut','suiviAmbu','bionettoyage','envoisInterop','preadmission','periopPlus','soinsPlus','sortiePlus','codage','iaTrace','droitsRgpd'],infirmier:['perop','rx','postopVitals','events','vpa','checklistBloc','blocStatut','suiviAmbu','bionettoyage','periopPlus','peropRapide','soinsPlus','sortiePlus','iaTrace'],secretariat:['core','preadmission'],dim:['codage']}[job]||[]).includes(module);
  if(group==='identities')return access.profile.isAdmin||job==='secretariat';
  if(group==='management'&&id==='planningResources')return access.profile.isAdmin;if(group==='management')return access.profile.isAdmin||({anesthesiste:['reservations','vacations','acts'],chirurgien:['reservations','vacations','acts'],secretariat:['reservations','vacations'],pharmacien:['lots','movements'],dim:['pmsi'],facturation:['invoices']}[job]||[]).includes(id);
  return false;
 }
 function setAccess(a){access=a;ctx.setProfile(a.profile,a.teams||[]);const header=$('#professional-identity');if(header)header.remove();const el=document.createElement('div');el.id='professional-identity';el.className='professional-identity';el.innerHTML=`<strong>${esc(a.profile.display_name)}</strong><span>${esc(libelle(a.profile))} · ${a.profile.active?'Compte actif':'Compte désactivé'}</span><span>${esc((a.teams||[]).map(t=>t.label).join(' · ')||'Aucune équipe active')}</span>`;document.querySelector('aside .asidebottom')?.prepend(el);}
 async function render(){document.querySelector('#title').textContent='Accès professionnels';document.querySelector('#stats').hidden=true;document.querySelector('#new').hidden=true;document.querySelectorAll('.nav[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view==='professionalAccess'));const host=$('#workspace');host.innerHTML='<section class="panel"><div class="content"><p>Chargement des habilitations…</p></div></section>';try{const d=await api();viewState=d;setAccess(d);host.innerHTML=`<section class="panel"><div class="content"><p class="eyebrow">COMPTES INDIVIDUELS ET IDENTITÉ PROFESSIONNELLE</p><h2>Accès professionnels</h2><p>La connexion du site identifie chaque compte. Le métier applicatif et les équipes sont attribués par l’administrateur, puis contrôlés à chaque requête serveur.</p><p class="notice">${esc(d.profile.display_name)} · ${esc(libelle(d.profile))} · ${d.profile.active?'actif':'désactivé'} · ${d.profile.isAdmin?'administrateur des habilitations':'utilisateur professionnel'}</p><p>Équipes actives : ${esc(d.teams.map(t=>t.label).join(' · ')||'aucune')} · ${d.stays.length} séjour(s) dans votre périmètre.</p><p class="muted">Prototype à patients fictifs. La connexion actuelle ne constitue pas une identification professionnelle par Pro Santé Connect. Le RPPS renseigné reste déclaratif et doit être vérifié avant le déploiement clinique.</p></div></section>${d.profile.isAdmin&&d.profile.active?adminMarkup(d):'<section class="panel"><div class="content"><h3>Vos habilitations</h3><p>Pour obtenir ou corriger une habilitation, contactez l’administrateur. Un accès à un dossier nécessite un métier autorisé et une équipe active affectée au séjour.</p></div></section>'}`;
 if(d.profile.isAdmin&&d.profile.active)bindAdmin(d);
 }catch(e){host.innerHTML=`<p class="notice warn">${esc(e.message)}</p>`;}}
 function adminMarkup(d){const accounts=d.accounts.map(a=>[a.user_id,a.display_name+' · '+(a.email||a.user_id)]),teams=d.allTeams.filter(t=>t.active).map(t=>[t.id,t.label]),today=new Date(),local=new Date(today-today.getTimezoneOffset()*60000).toISOString().slice(0,16);
 return `<section class="panel" id="access-create-panel"><div class="content"><h3>Créer un compte</h3><p class="muted">Réservé à l’administrateur. Un mot de passe provisoire est affiché une seule fois : remettez-le en main propre au professionnel, qui devra le changer à sa première connexion. Aucune invitation n’est envoyée.</p><form id="access-create"><div class="formgrid">${field('name','Nom et prénom (ex. Dr Jeanne Martin)')}${field('email','E-mail professionnel (identifiant)','email')}${select('profession','Métier',metiers.filter(([id])=>id!=='unassigned'),'chirurgien')}${field('rpps','RPPS (facultatif, 11 chiffres)','text','',false)}</div><p role="alert" class="management-error"></p><button class="primary">Créer le compte</button></form><div id="access-create-result" hidden></div></div></section><div class="professional-grid">${form('access-account','Métier et état du compte',select('userId','Compte individuel',accounts)+select('profession','Métier',metiers)+select('active','État du compte',[['true','Actif'],['false','Désactivé']])+field('rpps','RPPS déclaratif (facultatif)','text','',false),'Enregistrer le compte')}${form('access-membership','Rattacher un professionnel à une équipe',select('userId','Professionnel',accounts)+select('teamId','Équipe de soins',teams)+field('validFrom','Début de l’habilitation','datetime-local',local)+field('validUntil','Fin de l’habilitation (vide : sans date de fin)','datetime-local','',false),'Enregistrer le rattachement')}${form('access-assignment','Affecter un séjour à une équipe',select('stayId','Séjour',d.allStays.map(id=>[id,id]))+select('teamId','Équipe prenant en charge le séjour',teams)+field('validFrom','Début de prise en charge','datetime-local',local)+field('validUntil','Fin de prise en charge (facultatif)','datetime-local','',false),'Enregistrer l’équipe du séjour')}${form('access-mfa','Double authentification (téléphone perdu ou changé)',select('userId','Compte individuel',accounts),'Réinitialiser la double authentification')}</div><section class="panel"><div class="content"><h3>Comptes et habilitations actuels</h3><div class="management-scroll"><table class="management-table"><thead><tr><th>Compte individuel</th><th>Métier</th><th>État</th><th>Équipes et périodes</th></tr></thead><tbody>${d.accounts.map(a=>`<tr><td>${esc(a.display_name)}<br><small>${esc(a.email||a.user_id)}</small></td><td>${esc(libelle(a))}</td><td>${a.active?'Actif':'Désactivé'}</td><td>${d.memberships.filter(m=>m.user_id===a.user_id).map(m=>esc(d.allTeams.find(t=>t.id===m.team_id)?.label||m.team_id)+' · '+esc(new Date(m.valid_from).toLocaleString('fr-FR'))+' / '+esc(m.valid_until?new Date(m.valid_until).toLocaleString('fr-FR'):'sans date de fin')).join('<br>')||'Aucune équipe'}</td></tr>`).join('')}</tbody></table></div><h3>Affectations des séjours</h3><div class="management-scroll"><table class="management-table"><thead><tr><th>Séjour</th><th>Équipe</th><th>Période</th></tr></thead><tbody>${d.assignments.map(s=>`<tr><td>${esc(s.stay_id)}</td><td>${esc(d.allTeams.find(t=>t.id===s.team_id)?.label||s.team_id)}</td><td>${esc(s.valid_from)} / ${esc(s.valid_until||'sans date de fin')}</td></tr>`).join('')}</tbody></table></div></div></section><section class="panel"><div class="content"><h3>Journal des consultations, modifications et refus</h3><form id="access-log"><div class="formgrid">${select('actor','Filtrer par compte',[['','Tous les comptes'],...accounts])}${field('target','Filtrer par dossier ou rubrique','text','',false)}</div><button class="secondary">Consulter le journal</button></form><div id="professional-log"></div></div></section>`;}
 function bindAdmin(d){bindCreate();const a=$('#access-account'),account=()=>{const v=d.accounts.find(x=>x.user_id===a.elements.userId.value);a.elements.profession.value=choix(v.profession,v.poste);a.elements.active.value=String(!!v.active);a.elements.rpps.value=v.rpps||''};a.elements.userId.onchange=account;account();const m=$('#access-mfa');if(m)m.onsubmit=async e=>{e.preventDefault();const b=e.submitter,al=m.querySelector('[role=alert]');al.textContent='';b.disabled=true;try{const r=await fetch('/api/admin/accounts/mfa-reset',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(m)))}),x=await r.json().catch(()=>({}));if(!r.ok)throw new Error(x.error||'Réinitialisation impossible.');m.reset();ctx.toast('Double authentification réinitialisée : le professionnel scannera un nouveau code à sa prochaine connexion. Action tracée.');}catch(err){al.textContent=err.message}b.disabled=false};for(const [id,path]of [['access-account','/account'],['access-membership','/membership'],['access-assignment','/assignment']]){const f=$('#'+id);f.onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(f));if(id==='access-account'){values.active=values.active==='true';Object.assign(values,vers(values.profession))};for(const k of ['validFrom','validUntil'])if(k in values)values[k]=values[k]?new Date(values[k]).toISOString():null;const b=e.submitter;b.disabled=true;try{await api(path,values);await render();ctx.toast('Habilitation enregistrée et tracée. Rechargez le dossier pour appliquer la nouvelle vue.');}catch(err){f.querySelector('[role=alert]').textContent=err.message;b.disabled=false;}}}
 const localDate=value=>value?new Date(new Date(value)-new Date(value).getTimezoneOffset()*60000).toISOString().slice(0,16):'';
 for(const [id,source,idField]of [['access-membership',d.memberships,'userId'],['access-assignment',d.assignments,'stayId']]){
  const f=$('#'+id),previous=()=>source.find(x=>(idField==='userId'?x.user_id:x.stay_id)===f.elements[idField].value&&x.team_id===f.elements.teamId.value);
  const fill=()=>{const row=previous();if(row){f.elements.validFrom.value=localDate(row.valid_from);f.elements.validUntil.value=localDate(row.valid_until)}};
  f.elements[idField].onchange=fill;f.elements.teamId.onchange=fill;fill();
  const revoke=document.createElement('button');revoke.type='button';revoke.className='secondary';revoke.textContent=idField==='userId'?'Révoquer ce rattachement':'Clore cette prise en charge';revoke.onclick=async()=>{const row=previous(),reason=f.elements.reason.value.trim();if(!row||reason.length<5){f.querySelector('[role=alert]').textContent='Sélectionnez une habilitation existante et indiquez un motif de cinq caractères au minimum.';return}try{await api(idField==='userId'?'/membership':'/assignment',{[idField]:f.elements[idField].value,teamId:row.team_id,validFrom:row.valid_from,validUntil:new Date().toISOString(),reason});await render();ctx.toast('Fin d’habilitation enregistrée et tracée.');}catch(e){f.querySelector('[role=alert]').textContent=e.message}};f.append(revoke);
 }
 const logForm=$('#access-log');logForm.onsubmit=e=>{e.preventDefault();loadLog(Object.fromEntries(new FormData(logForm)))};
 }
 function bindCreate(){const f=$('#access-create');if(!f)return;f.onsubmit=async e=>{e.preventDefault();const b=e.submitter||f.querySelector('button'),alert=f.querySelector('[role=alert]');alert.textContent='';b.disabled=true;
  try{const r=await fetch('/api/admin/accounts',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify((v=>({...v,...vers(v.profession)}))(Object.fromEntries(new FormData(f))))}),x=await r.json();if(!r.ok)throw new Error(x.error||'Création impossible');
   await render();const out=$('#access-create-result');out.hidden=false;out.innerHTML=`<div class="notice"><p><strong>Compte créé : ${esc(x.email)}</strong></p><p>Mot de passe provisoire, affiché une seule fois : <code id="access-temp">${esc(x.temporaryPassword)}</code> <button type="button" class="secondary" id="access-temp-copy">Copier</button></p><p class="muted">Le professionnel se connecte avec son e-mail et ce mot de passe, puis choisit le sien. Il est rattaché à toutes les équipes de soins et voit donc les séjours ; un rattachement peut être révoqué ci-dessous.</p></div>`;
   $('#access-temp-copy').onclick=()=>navigator.clipboard?.writeText(x.temporaryPassword).then(()=>ctx.toast('Mot de passe provisoire copié')).catch(()=>{});out.scrollIntoView({block:'center'});ctx.toast('Compte créé et tracé.');
  }catch(err){alert.textContent=err.message;b.disabled=false}}}
 async function loadLog(filters,before){const host=$('#professional-log');host.textContent='Chargement du journal…';try{const query=new URLSearchParams({...filters,...(before?{before}: {})});const d=await api('/log?'+query);host.innerHTML=`<div class="management-scroll"><table class="management-table"><thead><tr><th>Date</th><th>Compte</th><th>Action</th><th>Dossier / cible</th><th>Résultat</th><th>Motif / détail</th></tr></thead><tbody>${d.entries.map(e=>`<tr><td>${esc(new Date(e.at).toLocaleString('fr-FR'))}</td><td>${esc(viewState.accounts.find(a=>a.user_id===e.actor)?.display_name||e.actor)}</td><td>${esc(e.action)}</td><td>${esc(e.target)}</td><td>${e.result==='denied'?'Refusé':'Autorisé'}</td><td>${esc(e.reason)}<br><small>${esc(e.detail)}</small></td></tr>`).join('')}</tbody></table></div>${d.hasMore?'<button class="secondary" id="access-log-older">Événements précédents</button>':''}`;if(d.hasMore)$('#access-log-older').onclick=()=>loadLog(filters,d.entries.at(-1).sequence);}catch(e){host.textContent=e.message}}
 function track(key,section){if(access?.profile.active)api('/view',{key,section}).catch(()=>{});}
 return {render,setAccess,canWrite,track,setPlanningOccupancy:rows=>{if(access)access.planningOccupancy=rows},getAccess:()=>access};
};
})(window);
